insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('258fd00d-cf28-455a-9a85-b1c67a1d8380', 'f72a3216-fdf3-42c3-a8de-52a4c3785b22', $$inleiding: belastingen buiten beschouwing; Kyano analyseert het jaarverslag van Pear nv$$,
   $$bedrijfseconomie-vwo-2026-i-pear-nv-context1.png$$,
   $$In deze opgave blijven belastingen buiten beschouwing.
Voor het vak bedrijfseconomie heeft Kyano de opdracht gekregen om een analyse te maken van het jaarverslag van technologiebedrijf Pear nv. Pear verkoopt mobiele telefoons, laptops en tablets. Op basis van dit jaarverslag moet hij een SWOT-analyse opstellen en een kengetallenanalyse maken.
De SWOT-analyse heeft Kyano al deels ingevuld.$$, 'inline'),
  ('4891df07-441d-413a-ad5f-c5198aac5007', 'f72a3216-fdf3-42c3-a8de-52a4c3785b22', $$deels ingevulde SWOT-analyse van Pear nv$$,
   $$bedrijfseconomie-vwo-2026-i-pear-nv-context2.png$$,
   $$SWOT-analyse (tabel met kolommen S, W, O, T)
S: − herkenbaar logo; − Producten zijn van topkwaliteit.
W: (leeg)
O: (leeg)
T: − Er komen meer concurrenten bij.; − Producten zijn duurder dan die van de concurrentie.; − afnemende vraag door economische neergang$$, 'inline'),
  ('6da8655b-d3da-4d76-8e5f-7cd790cc9325', 'f72a3216-fdf3-42c3-a8de-52a4c3785b22', $$fout bij de opsomming van de Threats$$,
